   176      if (p->value != 0) {
   177          vcardvalue_set_parent(p->value, 0);
   178          vcardvalue_free(p->value);
   179      }
   180
   181      while ((param = icalpvl_pop(p->parameters)) != 0) {
   182          vcardparameter_free(param);
   183      }
   184
   185      icalpvl_free(p->parameters);
   186
   187      if (p->x_name != 0) {
   188          icalmemory_free_buffer(p->x_name);
